import pandas as pd
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import matplotlib.ticker as mticker
import seaborn as sns
from scipy import stats
import base64
from io import BytesIO
import warnings
warnings.filterwarnings('ignore')

# ── Style Setup ──────────────────────────────────────────────────────
plt.rcParams.update({
    'figure.facecolor': '#FFFFFF',
    'axes.facecolor': '#F8F9FA',
    'axes.edgecolor': '#DEE2E6',
    'axes.grid': True,
    'grid.color': '#E9ECEF',
    'grid.linewidth': 0.8,
    'font.family': 'sans-serif',
    'font.size': 11,
    'axes.titlesize': 14,
    'axes.titleweight': 'bold',
    'axes.labelsize': 12,
})

BLUE = '#2C5F8A'
TEAL = '#2A9D8F'
ORANGE = '#E76F51'
GOLD = '#E9C46A'
DARK = '#1D3557'
LIGHT_BG = '#F1FAEE'
GREY = '#6C757D'

# ── Load Data ────────────────────────────────────────────────────────
df = pd.read_csv('/app/benchmark/data.csv')
df.columns = df.columns.str.strip()

# ── Computed KPIs ────────────────────────────────────────────────────
total_records = len(df)
unique_books = df['Name'].nunique()
unique_authors = df['Author'].nunique()
avg_rating = df['User Rating'].mean()
avg_price = df['Price'].mean()
avg_reviews = df['Reviews'].mean()
median_price = df['Price'].median()

fiction = df[df['Genre'] == 'Fiction']
nonfiction = df[df['Genre'] == 'Non Fiction']

fic_count = len(fiction)
nf_count = len(nonfiction)
fic_avg_rating = fiction['User Rating'].mean()
nf_avg_rating = nonfiction['User Rating'].mean()
fic_avg_price = fiction['Price'].mean()
nf_avg_price = nonfiction['Price'].mean()
fic_avg_reviews = fiction['Reviews'].mean()
nf_avg_reviews = nonfiction['Reviews'].mean()

# Pearson correlation
pearson_r, pearson_p = stats.pearsonr(df['Price'], df['User Rating'])

# By-genre Pearson
fic_r, fic_p = stats.pearsonr(fiction['Price'], fiction['User Rating'])
nf_r, nf_p = stats.pearsonr(nonfiction['Price'], nonfiction['User Rating'])

# Yearly aggregates
yearly = df.groupby('Year').agg(
    avg_price=('Price', 'mean'),
    avg_rating=('User Rating', 'mean'),
    avg_reviews=('Reviews', 'mean'),
    count=('Name', 'count')
).reset_index()

yearly_fic = fiction.groupby('Year').agg(
    avg_price=('Price', 'mean'),
    avg_rating=('User Rating', 'mean'),
).reset_index()

yearly_nf = nonfiction.groupby('Year').agg(
    avg_price=('Price', 'mean'),
    avg_rating=('User Rating', 'mean'),
).reset_index()

# Top authors
author_stats = df.groupby('Author').agg(
    appearances=('Name', 'count'),
    avg_rating=('User Rating', 'mean'),
    avg_price=('Price', 'mean'),
    total_reviews=('Reviews', 'sum')
).reset_index().sort_values('appearances', ascending=False)

top_authors = author_stats.head(12)

# Price segments
bins = [0, 5, 10, 15, 20, 30, 50, 200]
labels = ['$0-5', '$6-10', '$11-15', '$16-20', '$21-30', '$31-50', '$50+']
df['Price_Segment'] = pd.cut(df['Price'], bins=bins, labels=labels, right=True, include_lowest=True)
seg_stats = df.groupby('Price_Segment', observed=True).agg(
    count=('Name', 'count'),
    avg_rating=('User Rating', 'mean'),
).reset_index()

# ── Chart Generation Helpers ─────────────────────────────────────────
def fig_to_b64(fig):
    buf = BytesIO()
    fig.savefig(buf, format='png', bbox_inches='tight', dpi=150)
    plt.close(fig)
    buf.seek(0)
    return base64.b64encode(buf.read()).decode()


# ── Chart 1: Price vs Rating Scatter ─────────────────────────────────
fig1, ax1 = plt.subplots(figsize=(10, 6))
ax1.scatter(fiction['Price'], fiction['User Rating'], alpha=0.45, s=40,
            color=BLUE, label='Fiction', edgecolors='white', linewidth=0.3)
ax1.scatter(nonfiction['Price'], nonfiction['User Rating'], alpha=0.45, s=40,
            color=ORANGE, label='Non Fiction', edgecolors='white', linewidth=0.3)
# Trend line
z = np.polyfit(df['Price'], df['User Rating'], 1)
p = np.poly1d(z)
x_line = np.linspace(df['Price'].min(), df['Price'].max(), 100)
ax1.plot(x_line, p(x_line), '--', color=GREY, linewidth=1.5, label=f'Trend (r={pearson_r:.3f})')
ax1.set_xlabel('Price ($)')
ax1.set_ylabel('User Rating')
ax1.set_title('Price vs. User Rating: Scatter Plot with Trend Line')
ax1.legend(frameon=True, fancybox=True, shadow=False)
ax1.set_ylim(3.0, 5.1)
chart1_b64 = fig_to_b64(fig1)


# ── Chart 2: Genre Comparison Bar ────────────────────────────────────
fig2, axes2 = plt.subplots(1, 3, figsize=(14, 4.5))
metrics = [('Avg Price ($)', [fic_avg_price, nf_avg_price], BLUE),
           ('Avg User Rating', [fic_avg_rating, nf_avg_rating], TEAL),
           ('Avg Reviews', [fic_avg_reviews, nf_avg_reviews], ORANGE)]
for ax, (title, vals, color) in zip(axes2, metrics):
    bars = ax.bar(['Fiction', 'Non Fiction'], vals, color=[BLUE, ORANGE], width=0.5, edgecolor='white')
    ax.set_title(title)
    for bar, val in zip(bars, vals):
        fmt = f'{val:,.0f}' if val > 100 else f'{val:.2f}'
        ax.text(bar.get_x() + bar.get_width()/2, bar.get_height() + (max(vals)*0.02),
                fmt, ha='center', va='bottom', fontweight='bold', fontsize=11)
    ax.set_ylim(0, max(vals) * 1.18)
fig2.suptitle('Fiction vs. Non Fiction: Key Metrics Comparison', fontsize=15, fontweight='bold', y=1.02)
fig2.tight_layout()
chart2_b64 = fig_to_b64(fig2)


# ── Chart 3: Yearly Price Trend (DUAL AXIS) ─────────────────────────
fig3, ax3a = plt.subplots(figsize=(11, 5.5))
ax3b = ax3a.twinx()

ax3a.plot(yearly['Year'], yearly['avg_price'], 'o-', color=BLUE, linewidth=2.2,
          markersize=7, label='Avg Price ($)', zorder=3)
ax3a.fill_between(yearly['Year'], yearly['avg_price'], alpha=0.08, color=BLUE)

ax3b.plot(yearly['Year'], yearly['avg_rating'], 's-', color=TEAL, linewidth=2.2,
          markersize=7, label='Avg Rating', zorder=3)
ax3b.fill_between(yearly['Year'], yearly['avg_rating'], alpha=0.08, color=TEAL)

ax3a.set_xlabel('Year')
ax3a.set_ylabel('Average Price ($)', color=BLUE)
ax3b.set_ylabel('Average User Rating', color=TEAL)
ax3a.set_xticks(yearly['Year'])
ax3a.tick_params(axis='y', labelcolor=BLUE)
ax3b.tick_params(axis='y', labelcolor=TEAL)
ax3b.set_ylim(4.2, 4.85)

lines1, labels1 = ax3a.get_legend_handles_labels()
lines2, labels2 = ax3b.get_legend_handles_labels()
ax3a.legend(lines1 + lines2, labels1 + labels2, loc='upper left', frameon=True)

ax3a.set_title('Year-over-Year Trends: Average Price and User Rating (2009–2019)', fontsize=13, fontweight='bold')
chart3_b64 = fig_to_b64(fig3)


# ── Chart 4: Yearly Price by Genre ───────────────────────────────────
fig4, ax4 = plt.subplots(figsize=(11, 5))
ax4.plot(yearly_fic['Year'], yearly_fic['avg_price'], 'o-', color=BLUE,
         linewidth=2, markersize=6, label='Fiction')
ax4.plot(yearly_nf['Year'], yearly_nf['avg_price'], 's-', color=ORANGE,
         linewidth=2, markersize=6, label='Non Fiction')
ax4.set_xlabel('Year')
ax4.set_ylabel('Average Price ($)')
ax4.set_xticks(yearly['Year'])
ax4.legend(frameon=True)
ax4.set_title('Average Price by Genre Over Time (2009–2019)', fontsize=13, fontweight='bold')
chart4_b64 = fig_to_b64(fig4)


# ── Chart 5: Yearly Rating by Genre ──────────────────────────────────
fig5, ax5 = plt.subplots(figsize=(11, 5))
ax5.plot(yearly_fic['Year'], yearly_fic['avg_rating'], 'o-', color=BLUE,
         linewidth=2, markersize=6, label='Fiction')
ax5.plot(yearly_nf['Year'], yearly_nf['avg_rating'], 's-', color=ORANGE,
         linewidth=2, markersize=6, label='Non Fiction')
ax5.set_xlabel('Year')
ax5.set_ylabel('Average User Rating')
ax5.set_xticks(yearly['Year'])
ax5.set_ylim(4.2, 4.85)
ax5.legend(frameon=True)
ax5.set_title('Average User Rating by Genre Over Time (2009–2019)', fontsize=13, fontweight='bold')
chart5_b64 = fig_to_b64(fig5)


# ── Chart 6: Yearly Reviews ──────────────────────────────────────────
fig6, ax6 = plt.subplots(figsize=(11, 5))
ax6.bar(yearly['Year'], yearly['avg_reviews'], color=BLUE, alpha=0.75, width=0.6, edgecolor='white')
for i, row in yearly.iterrows():
    ax6.text(row['Year'], row['avg_reviews'] + 200, f'{row["avg_reviews"]:,.0f}',
             ha='center', va='bottom', fontsize=9, fontweight='bold')
ax6.set_xlabel('Year')
ax6.set_ylabel('Average Reviews per Book')
ax6.set_xticks(yearly['Year'])
ax6.set_title('Average Review Volume by Year (2009–2019)', fontsize=13, fontweight='bold')
chart6_b64 = fig_to_b64(fig6)


# ── Chart 7: Top Authors ─────────────────────────────────────────────
fig7, ax7 = plt.subplots(figsize=(10, 6))
top_a = top_authors.head(10).sort_values('appearances', ascending=True)
colors = [BLUE if v >= 8 else TEAL for v in top_a['appearances']]
bars = ax7.barh(top_a['Author'], top_a['appearances'], color=colors, edgecolor='white', height=0.6)
for bar, val, rating in zip(bars, top_a['appearances'], top_a['avg_rating']):
    ax7.text(bar.get_width() + 0.2, bar.get_y() + bar.get_height()/2,
             f'{val} appearances  (avg {rating:.2f})', va='center', fontsize=10)
ax7.set_xlabel('Number of Bestseller Appearances')
