chart7_b64 = fig_to_b64(fig7)


# ── Chart 8: Price Segment Distribution ──────────────────────────────
fig8, ax8 = plt.subplots(figsize=(10, 5))
bar_colors = [BLUE if s != '$50+' else ORANGE for s in seg_stats['Price_Segment']]
bars = ax8.bar(seg_stats['Price_Segment'].astype(str), seg_stats['count'],
