for bar, cnt, rat in zip(bars, seg_stats['count'], seg_stats['avg_rating']):
    ax8.text(bar.get_x() + bar.get_width()/2, bar.get_height() + 3,
             f'{cnt}\n({rat:.2f})', ha='center', va='bottom', fontsize=9, fontweight='bold')
ax8.set_xlabel('Price Segment')
ax8.set_ylabel('Number of Bestseller Entries')
ax8.set_title('Bestseller Distribution by Price Segment (avg rating in parentheses)', fontsize=13, fontweight='bold')
chart8_b64 = fig_to_b64(fig8)


# ── Chart 9: Rating Distribution ─────────────────────────────────────
fig9, ax9 = plt.subplots(figsize=(9, 5))
